<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { RouterLink } from 'vue-router'
import FogVillageScene from '@/components/FogVillageScene.vue'
import PixelTitle from '@/components/PixelTitle.vue'
import VillageHeader from '@/components/VillageHeader.vue'
import GameTable from '@/components/GameTable.vue'
import PixelAvatar from '@/components/PixelAvatar.vue'
import PixelIcon from '@/components/PixelIcon.vue'
import PixelDialog from '@/components/PixelDialog.vue'
import { useLabStore } from '@/stores/lab'
import { usingRealBackend } from '@/api/adapters'
import { useObservationStore } from '@/stores/observation'
import { useHomeDemoStore } from '@/stores/homeDemo'
import { useVillageAudio } from '@/features/home/useVillageAudio'
import { roleNames } from '@/features/game/types'
import { formatTime } from '@/features/observation/types'
import { defaultPrompt, metricNames, personalities, ruleBaselineModel, strategies } from '@/features/lab/types'
import type { ComparisonMetric, ComparisonRow, LabBatchGame, LabRole } from '@/features/lab/types'

const lab = useLabStore(), preview = useObservationStore()
/**
 * 真实模式：配置与批次走服务端 `/lab/*`，对局由服务端用与真人对局相同的路径推进。
 *
 * 演示专属的控件（本地对局工作台、随机种子、演示速度、清空本地记录、工具开关、自定义提示词）
 * 在真实模式下**隐藏而不是保留**：它们背后没有服务端消费点，
 * 留着会让"我关了历史工具"变成一个看起来生效、实际无效的设置。
 */
const real = usingRealBackend()
const dialog = ref<'rules' | 'about' | 'audio' | 'configs' | 'model' | 'advanced' | 'report' | 'clear' | 'seat' | null>(null)
const view = ref<'table' | 'log'>('table'), logTab = ref<'speech' | 'summary' | 'event'>('speech'), logDetail = ref('normal'), logSeat = ref('all')
const showRoles = ref(true), selectedSeat = ref<number | null>(null), modelDetail = ref(''), resultHeading = ref<HTMLElement | null>(null)
const autoScroll = ref(true), logList = ref<HTMLElement | null>(null), exportFeedback = ref('')
const { sound, toggleSound } = useVillageAudio(() => { dialog.value = 'audio' })
const roles: { role: LabRole; avatar: 'red' | 'blue' | 'owl' | 'green'; icon: string }[] = [{ role: 'WEREWOLF', avatar: 'red', icon: 'wolf' }, { role: 'SEER', avatar: 'blue', icon: 'eye' }, { role: 'WITCH', avatar: 'owl', icon: 'bottle' }, { role: 'HUNTER', avatar: 'green', icon: 'gun' }, { role: 'VILLAGER', avatar: 'green', icon: 'leaf' }]
const model = computed(() => lab.models.find(item => item.id === (modelDetail.value || lab.draft?.modelId)))
const tablePlayers = computed(() => preview.view?.players.map(person => ({ ...person, disclosedRole: showRoles.value ? person.disclosedRole : undefined })) || [])
const inspected = computed(() => preview.match?.players.find(person => person.seatNo === selectedSeat.value))
const logs = computed(() => preview.visibleEvents.filter(event => event.at <= preview.position && (logSeat.value === 'all' || event.seatNo === Number(logSeat.value)) && (logTab.value === 'event' || logTab.value === 'summary' && !!event.rationale || logTab.value === 'speech' && event.type === 'PLAYER_SPOKE')).reverse().slice(0, logDetail.value === 'normal' ? 4 : 12))
const batchState = computed(() => lab.running ? (real ? '批次进行中' : '演示进行中') : lab.batch ? (real ? '批次已完成' : '演示已完成') : '待开始测试')
const comparisonSource = computed(() => lab.batch ? (real ? `当前批次 · 已结束 ${lab.completedGames} 局` : `当前批次 · ${lab.completedGames} 局样例`) : lab.comparisons.length ? (real ? '目录内全部已结束批次' : '预置比较样例 · 20 局') : '暂无实验记录')
/** 服务端一个模型都没配时会话里只有规则机器人这一项，界面要据此说清"为什么不能选模型"。 */
const ruleBaselineOnly = computed(() => lab.models.length > 0 && lab.models.every(model => model.id === ruleBaselineModel.id))
const title = computed(() => ({ rules: '经典九人规则', about: '关于 AI 实验室', audio: '音效暂时不可用', configs: '已保存配置与批次选择', model: real ? '模型详情' : '示例模型详情', advanced: '高级设置', report: real ? '实验报告' : '本地实验报告', clear: '清空本地记录', seat: '样例玩家信息' }[dialog.value || 'about']))
const gameStatusNames: Record<LabBatchGame['status'], string> = { PENDING: '待开局', RUNNING: '进行中', FINISHED: '已结束', ABORTED: '已中止', FAILED: '失败' }
/** 逐局状态文案：真实模式下列表要能回答"这一局跑完了吗、谁赢了"。 */
function gameLabel(game: LabBatchGame) { return [gameStatusNames[game.status], game.winner ? `${game.winner}获胜` : '', game.rounds ? `${game.rounds} 轮` : ''].filter(Boolean).join(' · ') }
function metricValue(row: ComparisonRow | null, key: ComparisonMetric) { const value = row?.[key]; return value == null ? '暂无数据' : `${value}${key === 'winRate' ? '%' : key === 'latency' ? 's' : ' 分'}` }
async function focusErrors() {
  const field = Object.keys(lab.fields)[0]
  if (field === 'temperature' || field === 'concurrency') dialog.value = 'advanced'
  await nextTick(); await nextTick()
  document.querySelector<HTMLElement>(`[data-lab-field="${field}"]`)?.focus()
}
async function save() { if (await lab.save()) { await nextTick(); resultHeading.value?.focus() } else if (Object.keys(lab.fields).length) await focusErrors() }
async function start() { if (await lab.start()) { await nextTick(); resultHeading.value?.focus() } else if (Object.keys(lab.fields).length) await focusErrors() }
function promptMode(mode: 'default' | 'custom') { if (lab.draft) { lab.draft.promptMode = mode; if (mode === 'default') lab.draft.prompt = defaultPrompt } }
function changeTotal(delta: number) { lab.options.total = Math.max(1, Math.min(50, (Number(lab.options.total) || 1) + delta)) }
function shuffleSeed() { const value = new Uint32Array(1); crypto.getRandomValues(value); lab.options.seedStart = value[0]! % 1000000 }
function inspect(seat: number) { selectedSeat.value = seat; dialog.value = 'seat' }
async function exportResults() {
  if (!lab.comparisons.length && !lab.batch?.results.length) return
  try {
    const blob = new Blob([JSON.stringify(lab.exportData(), null, 2)], { type: 'application/json;charset=utf-8' })
    const url = URL.createObjectURL(blob), link = document.createElement('a')
    link.href = url; link.download = `wolfmind-${lab.batch?.id || 'lab-reference'}.json`; link.click(); URL.revokeObjectURL(url)
    exportFeedback.value = real ? '已导出 JSON，来源标注为服务端实验室。' : '已导出 JSON，其中已标注本地示例来源。'
  } catch { exportFeedback.value = '下载不可用，请使用报告中的文本结果。' }
}
watch(() => [lab.options.total, lab.options.seedStart], () => { if (Number.isInteger(lab.options.total) && Number.isInteger(lab.options.seedStart)) lab.options.seedEnd = lab.options.seedStart + lab.options.total - 1 })
watch(logs, async () => { if (autoScroll.value) { await nextTick(); if (logList.value) logList.value.scrollTop = 0 } })
onMounted(() => { useHomeDemoStore().phase = 'night'; void lab.load(); if (!real) void preview.load('demo') })
onBeforeUnmount(() => { lab.dispose(); preview.dispose() })
</script>

<template>
  <div class="landing inner-page lab-page is-night">
    <FogVillageScene controlled-phase="night" hide-actors />
    <VillageHeader :sound="sound" @sound="toggleSound" @info="dialog = $event" />
    <main class="lab-main">
      <nav class="lab-nav" aria-label="实验导航"><span aria-current="page">AI 实验室</span><template v-if="!real"><RouterLink to="/watch/demo">AI 对局</RouterLink><RouterLink to="/games/demo/analysis">AI 分析</RouterLink></template><template v-else-if="lab.latestGame?.gameId"><RouterLink :to="`/watch/${lab.latestGame.gameId}`">AI 对局</RouterLink><RouterLink :to="`/games/${lab.latestGame.gameId}/analysis`">AI 分析</RouterLink></template><RouterLink to="/lobby">游戏大厅</RouterLink></nav>
      <div class="lab-heading"><span>AI LAB</span><h1><PixelTitle text="AI 实验室" :size="16" /></h1><p>配置、测试、对比不同的 AI Agent，回看营火旁的策略与选择。</p><small>{{ real ? '服务端实验室 · 批次对局与真人对局走同一条规则与驱动；胜率来自已结束的对局' : '本地实验示例 · 不调用真实模型，指标为手工编写的样例' }}</small></div>
      <section v-if="lab.loading" class="px-panel observation-state" role="status"><h2>正在载入实验室…</h2><p>{{ real ? '读取 Agent 配置与最近一次批次进度。' : '读取 Agent 配置和示例结果。' }}</p></section>
      <section v-else-if="lab.restricted || lab.error && !lab.models.length" class="px-panel observation-state" role="alert"><h2>{{ lab.restricted ? '没有实验室权限' : '实验室加载失败' }}</h2><p>{{ lab.error || lab.comparisonError }}</p><button v-if="!lab.restricted" class="secondary-button px-button" @click="lab.load">重试</button><RouterLink to="/lobby" class="secondary-button px-button">返回大厅</RouterLink></section>
      <template v-else>
        <p v-if="lab.error" class="lab-alert" role="alert">{{ lab.error }} <button @click="lab.error = ''">关闭提示</button></p>
        <p v-if="lab.feedback || exportFeedback" class="lab-feedback" role="status">{{ exportFeedback || lab.feedback }}</p>
        <div class="lab-layout" :class="{ 'lab-online-layout': real }">
          <form class="px-panel lab-panel lab-config" aria-label="Agent 配置" @submit.prevent="save">
            <div class="lab-panel-title"><h2><PixelIcon name="settings" :size="22" /> 配置 Agent</h2><button type="submit" class="lab-outline" :disabled="!lab.draft || lab.saving">{{ lab.saving ? '保存中…' : '保存配置' }}</button></div>
            <div class="lab-config-picker"><label><span class="sr-only">已保存配置</span><select :value="lab.draft?.id || ''" @change="lab.selectConfig(($event.target as HTMLSelectElement).value)"><option v-if="!lab.draft?.id" value="">{{ lab.draft ? '未保存配置' : '还没有 Agent 配置' }}</option><option v-for="config in lab.configs" :key="config.id" :value="config.id">{{ config.name }}</option></select></label><button type="button" class="lab-link" :disabled="!lab.canCreate" @click="lab.newConfig">＋ 新建</button><button type="button" class="lab-link" @click="dialog = 'configs'">配置库</button></div>
            <p v-if="!lab.draft" class="game-muted">还没有 Agent 配置，点击“新建”开始。</p>
            <div v-if="!lab.draft && real" class="lab-empty-config">
              <p v-if="ruleBaselineOnly" class="game-muted">服务端没有可用的模型配置，因此新建的配置只能选“规则机器人（不使用模型）”：它不调用模型，由确定性规则基线出招。要跑真实模型，需要管理员配置 WOLFMIND_LLM_PROVIDER / WOLFMIND_LLM_MODEL / WOLFMIND_LLM_API_KEY 后刷新本页。</p>
              <button type="button" class="primary-button px-button px-button-primary" :disabled="!lab.canCreate" @click="lab.newConfig">＋ 新建 Agent 配置</button>
            </div>
            <fieldset v-if="lab.draft" class="lab-config-fields" :disabled="lab.saving">
              <label class="lab-name"><span>配置名称</span><input v-model="lab.draft.name" data-lab-field="name" maxlength="24" :aria-invalid="!!lab.fields.name" aria-describedby="lab-name-error" /></label><p v-if="lab.fields.name" id="lab-name-error" class="lab-field-error">{{ lab.fields.name }}</p>
              <section class="lab-config-section"><h3><b>1</b>角色分配</h3><div class="lab-role-buttons" aria-label="角色选择"><button v-for="role in roles" :key="role.role" type="button" :aria-pressed="lab.draft.role === role.role" :class="{ active: lab.draft.role === role.role }" @click="lab.draft.role = role.role"><PixelAvatar :variant="role.avatar" :size="29" /><span>{{ roleNames[role.role] }}</span></button></div><p class="lab-hint">当前配置：{{ roleNames[lab.draft.role] }} · {{ lab.draft.strategy }}</p></section>
              <section class="lab-config-section"><h3><b>2</b>性格风格</h3><div class="lab-choice-grid" aria-label="性格风格"><button v-for="style in personalities" :key="style" type="button" :class="{ active: lab.draft.personality === style }" :aria-pressed="lab.draft.personality === style" @click="lab.draft.personality = style"><span aria-hidden="true">{{ lab.draft.personality === style ? '●' : '◇' }}</span>{{ style }}</button></div><p class="lab-hint">发言与判断的风格配置，角色信息边界仍须遵守。</p></section>
              <section class="lab-config-section"><h3><b>3</b><label for="lab-strategy">策略预设</label></h3><select id="lab-strategy" v-model="lab.draft.strategy"><option v-for="strategy in strategies" :key="strategy">{{ strategy }}</option></select></section>
              <section class="lab-config-section"><h3><b>4</b><label for="lab-model">模型选择</label></h3><div class="lab-model-choice"><PixelAvatar :variant="lab.models.find(item => item.id === lab.draft?.modelId)?.avatar || 'fox'" :size="26" /><select id="lab-model" v-model="lab.draft.modelId" data-lab-field="modelId" :aria-invalid="!!lab.fields.modelId"><option v-for="item in lab.models" :key="item.id" :value="item.id">{{ item.name }}</option></select><button type="button" aria-label="查看所选模型详情" @click="modelDetail = lab.draft.modelId; dialog = 'model'"><PixelIcon name="eye" :size="17" /></button></div><p v-if="lab.fields.modelId" class="lab-field-error">{{ lab.fields.modelId }}</p></section>
              <section class="lab-config-section"><h3><b>5</b>提示词配置</h3><div class="lab-prompt-tabs"><button type="button" :aria-pressed="lab.draft.promptMode === 'default'" :class="{ active: lab.draft.promptMode === 'default' }" @click="promptMode('default')">默认模板</button><button type="button" :aria-pressed="lab.draft.promptMode === 'custom'" :class="{ active: lab.draft.promptMode === 'custom' }" @click="promptMode('custom')">{{ real ? '自定义模板标识' : '自定义指令' }}</button></div><label class="sr-only" for="lab-prompt">Agent 提示词</label><textarea id="lab-prompt" v-model="lab.draft.prompt" data-lab-field="prompt" rows="3" maxlength="800" :readonly="real || lab.draft.promptMode === 'default'" :aria-invalid="!!lab.fields.prompt" :aria-describedby="real ? 'lab-prompt-error lab-prompt-note' : 'lab-prompt-error'" /><div class="lab-textarea-footer"><small>{{ real ? '正文不会被发送或保存' : '仅使用角色可见信息' }}</small><span>{{ lab.draft.prompt.length }}/800</span></div><p v-if="real" id="lab-prompt-note" class="lab-hint">模板标识（<code>promptTemplateId</code>）只作为比对维度记录进轨迹与统计，当前不改变提示词装配，正文也不在服务端契约里——所以这里不可编辑，也没有可保存的正文。</p><p v-if="lab.fields.prompt" id="lab-prompt-error" class="lab-field-error">{{ lab.fields.prompt }}</p></section>
              <section class="lab-config-section"><h3><b>6</b>记忆模式</h3><div class="lab-prompt-tabs"><button v-for="(label, key) in { short: '短期记忆', long: '长期记忆', off: '关闭' }" :key="key" type="button" :class="{ active: lab.draft.memory === key }" :aria-pressed="lab.draft.memory === key" @click="lab.draft.memory = key">{{ label }}</button></div><p class="lab-hint">仅为配置选项，本地示例不会调用模型记忆。</p></section>
              <section v-if="!real" class="lab-config-section lab-tools"><h3><b>7</b>工具权限</h3><label><input v-model="lab.draft.tools.analysis" type="checkbox" />分析公开记录</label><label><input v-model="lab.draft.tools.history" type="checkbox" />查看历史对局</label><label><input v-model="lab.draft.tools.summary" type="checkbox" />生成决策摘要</label><span>外部联网：未开放</span></section>
            </fieldset>
          </form>
          <section v-if="real" class="px-panel lab-panel lab-workbench" aria-label="实验说明">
            <div class="lab-panel-title"><h2><PixelIcon name="shield" :size="22" /> 实验如何进行</h2></div>
            <ol class="lab-config-section">
              <li>保存 Agent 配置：角色、模型、温度、策略档位、人格与记忆模式都有运行时消费点；提示词只保存模板标识，作为比对维度。</li>
              <li>创建批次：服务端按并发上限逐局开局，使用与真人对局完全相同的规则、事件流与驱动。</li>
              <li>点「刷新进度」读取结果：胜率 = 该配置所在阵营获胜的局数 / 该配置参与且已结束的局数。</li>
            </ol>
            <p class="game-muted">批次对局就是普通对局：下面「批次对局」按真实 <code>gameId</code> 列出每一局，可直接观战、回放与单局分析——它们不是实验室的私有格式。</p>
            <p class="game-muted">Token 与耗时来自服务的决策轨迹（AGENT_LLM_INVOKED）；规则基线座位为 0，表示这一局没有花模型成本。</p>
          </section>
          <section v-if="real" class="px-panel lab-panel lab-games" aria-label="批次对局">
            <div class="lab-panel-title"><h2><PixelIcon name="wolf" :size="22" /> 批次对局</h2></div>
            <ol v-if="lab.batch?.games.length" class="lab-game-results">
              <li v-for="game in lab.batch.games" :key="game.index"><span><strong>第 {{ game.index }} 局</strong><small>{{ game.gameId || '尚未开局' }} · {{ gameLabel(game) }}</small></span><span v-if="game.gameId"><RouterLink :to="`/watch/${game.gameId}`">观战</RouterLink><RouterLink :to="`/games/${game.gameId}/replay`">回放</RouterLink><RouterLink :to="`/games/${game.gameId}/analysis`">分析</RouterLink></span></li>
            </ol>
            <p v-else class="game-muted">{{ lab.batch ? '批次已创建，服务端还没开出对局；点“刷新进度”查看。' : '还没有批次：保存配置后点“开始测试”，这里会按真实对局 id 列出每一局。' }}</p>
          </section>
          <section v-if="!real" class="px-panel lab-panel lab-workbench" aria-label="实验工作台">
            <div class="lab-panel-title"><h2><PixelIcon name="gamepad" :size="22" /> 实验工作台</h2><div class="lab-workbench-tabs"><button :aria-pressed="showRoles" @click="showRoles = !showRoles">{{ showRoles ? '隐藏身份' : '赛后身份' }}</button><button :class="{ active: view === 'table' }" :aria-pressed="view === 'table'" @click="view = 'table'">对局预览</button><button :class="{ active: view === 'log' }" :aria-pressed="view === 'log'" @click="view = 'log'">日志视图</button></div></div>
            <div v-if="preview.loading" class="lab-preview-state" role="status">正在读取只读样例…</div><div v-else-if="preview.error" class="lab-preview-state" role="alert">{{ preview.error }}<button class="secondary-button px-button" @click="preview.load('demo')">重试样例</button></div>
            <template v-else-if="preview.view && preview.match"><div class="lab-phase"><PixelIcon :name="preview.view.atmosphere === 'night' ? 'moon' : 'sun'" :size="30" /><div><h3>第 {{ preview.view.round }} 天 · {{ preview.view.phase }}</h3><p>只读九人对局样例 · 与批次样例结果独立</p></div></div><div v-if="view === 'table'" class="lab-board"><GameTable :players="tablePlayers" :phase="preview.view.atmosphere" :me="0" :speaker="preview.view.speaker" :selected="null" :targets="[]" :selecting="false" @choose="inspect" /></div><div v-else class="lab-full-log"><h3>系统事件 · 已播放记录</h3><ol><li v-for="event in preview.visibleEvents.filter(item => item.at <= preview.position)" :key="event.id"><time>{{ formatTime(event.at) }}</time><strong>{{ event.title }}</strong><p>{{ event.content }}</p></li></ol></div><div class="lab-log-toolbar"><div><button v-for="(label, key) in { speech: '对局日志', summary: 'Agent 摘要', event: '系统事件' }" :key="key" :class="{ active: logTab === key }" :aria-pressed="logTab === key" @click="logTab = key">{{ label }}</button></div><label><span class="sr-only">日志玩家筛选</span><select v-model="logSeat"><option value="all">全部玩家</option><option v-for="person in preview.match.players" :key="person.seatNo" :value="String(person.seatNo)">{{ person.seatNo }} 号</option></select></label></div><ul v-if="logs.length" ref="logList" class="lab-log-list"><li v-for="event in logs" :key="event.id"><PixelIcon name="check" :size="14" /><time>{{ formatTime(event.at) }}</time><PixelAvatar v-if="event.seatNo" :variant="preview.match.players.find(person => person.seatNo === event.seatNo)!.avatar" :size="22" /><span><strong>{{ event.seatNo ? `${event.seatNo} 号 ${preview.match.players.find(person => person.seatNo === event.seatNo)?.name}` : event.title }}</strong><small>{{ logTab === 'summary' ? event.rationale : event.content }}</small><small v-if="logDetail === 'detail'" class="lab-log-meta">{{ event.id }} · v{{ event.version }} · {{ event.scope }}</small></span></li></ul><p v-else class="lab-preview-state">当前筛选下没有已播放记录。</p></template>
          </section>
          <aside class="px-panel lab-right">
            <section class="lab-panel lab-batch"><div class="lab-panel-title"><h2><PixelIcon name="bottle" :size="22" /> 批量测试</h2><button class="lab-subtle" @click="dialog = 'configs'">加载配置</button></div><div class="lab-batch-content"><div class="lab-batch-form"><label class="lab-batch-row"><span>对局次数</span><span class="lab-stepper"><button aria-label="减少对局次数" :disabled="lab.options.total <= 1" @click.prevent="changeTotal(-1)">−</button><input v-model.number="lab.options.total" type="number" min="1" max="50" data-lab-field="total" :aria-invalid="!!lab.fields.total" /><button aria-label="增加对局次数" :disabled="lab.options.total >= 50" @click.prevent="changeTotal(1)">＋</button></span><small>次</small></label><p v-if="lab.fields.total" class="lab-field-error">{{ lab.fields.total }}</p><div v-if="!real" class="lab-batch-row"><span>随机种子</span><label><span class="sr-only">起始种子</span><input v-model.number="lab.options.seedStart" type="number" min="0" data-lab-field="seedStart" :aria-invalid="!!lab.fields.seedStart" /></label><span>–</span><label><span class="sr-only">结束种子</span><input v-model.number="lab.options.seedEnd" type="number" min="0" data-lab-field="seedEnd" :aria-invalid="!!lab.fields.seedEnd" /></label><button aria-label="随机选择种子范围" class="lab-square" @click="shuffleSeed"><PixelIcon name="refresh" :size="16" /></button></div><p v-if="lab.fields.seedStart || lab.fields.seedEnd" class="lab-field-error">{{ lab.fields.seedStart || lab.fields.seedEnd }}</p><div v-if="!real" class="lab-batch-row"><span>测试模式</span><div class="lab-inline-choices"><button :class="{ active: lab.options.mode === 'standard' }" :aria-pressed="lab.options.mode === 'standard'" @click="lab.options.mode = 'standard'">标准演示</button><button :class="{ active: lab.options.mode === 'quick' }" :aria-pressed="lab.options.mode === 'quick'" @click="lab.options.mode = 'quick'">快速演示</button><button @click="dialog = 'rules'">规则配置</button></div></div><div v-if="!real" class="lab-batch-row"><span>演示速度</span><div class="lab-inline-choices"><button v-for="speed in [0.5, 1, 2, 5]" :key="speed" :aria-pressed="lab.options.speed === speed" :class="{ active: lab.options.speed === speed }" @click="lab.options.speed = speed">{{ speed }}x</button></div></div><p class="lab-hint lab-selected-count">已选择 {{ lab.selectedIds.length }} 份保存配置 · 并发上限 {{ lab.options.concurrency }} <button class="lab-link" @click="dialog = 'configs'">更改</button></p><p v-if="lab.fields.configIds" class="lab-field-error">{{ lab.fields.configIds }}</p><div class="lab-batch-actions"><button class="primary-button px-button px-button-primary" data-lab-field="configIds" :disabled="lab.running || lab.submitting || lab.clearing" @click="start"><PixelIcon name="play" :size="17" />{{ lab.submitting ? '创建中…' : '开始测试' }}</button><button class="lab-subtle" @click="dialog = 'advanced'"><PixelIcon name="settings" :size="16" />高级设置</button></div><button v-if="lab.batch" class="lab-refresh" :disabled="lab.refreshing || !lab.running" @click="lab.refresh"><PixelIcon name="refresh" :size="16" />{{ lab.refreshing ? '正在刷新…' : lab.running ? '刷新进度' : '批次已完成' }}</button></div><div class="lab-progress"><h3>测试进度</h3><div class="lab-progress-ring" :style="{ '--lab-progress': `${lab.progress}%` }"><strong>{{ lab.progress }}%</strong></div><p><strong>{{ lab.batch ? lab.completedGames : 0 }}</strong> / {{ lab.batch ? lab.totalGames : lab.options.total }} 局</p><small>{{ batchState }}</small><ol><li>✓ {{ lab.batch ? '已加载配置快照' : '等待配置提交' }}</li><li>{{ lab.running ? (real ? '● 服务端正在推进对局' : '● 正在展示样例') : lab.batch ? (real ? '✓ 批次已结束' : '✓ 样例展示完成') : '○ 尚未开始' }}</li><li>{{ lab.batch?.status === 'COMPLETED' ? '✓ 汇总结果已生成' : '○ 等待汇总结果' }}</li></ol></div></div><p class="lab-hint">{{ real ? '服务端按并发上限推进对局；点“刷新进度”读取最新结果。' : '手动刷新推进预置样例；正式进度由服务端返回。' }}</p></section>
            <section class="lab-panel lab-comparison" :aria-busy="lab.comparing"><div class="lab-panel-title"><h2><PixelIcon name="ballot" :size="22" /> 模型比较</h2><label><span class="sr-only">比较维度</span><select v-model="lab.metric"><option v-for="(label, key) in metricNames" :key="key" :value="key">按{{ label }}排序</option></select></label></div><div class="lab-comparison-filters"><small>{{ comparisonSource }}</small><label><span class="sr-only">比较角色筛选</span><select v-model="lab.roleFilter"><option value="all">全部角色</option><option v-for="role in roles" :key="role.role" :value="role.role">{{ roleNames[role.role] }}</option></select></label><button class="lab-link" :disabled="lab.comparing" @click="lab.compare">{{ lab.comparing ? '读取中…' : '刷新比较' }}</button></div><p v-if="lab.comparisonError" class="lab-field-error" role="alert">{{ lab.comparisonError }} <button class="lab-link" @click="lab.compare">重试比较</button></p><div v-if="lab.rows.length" class="lab-table-scroll"><table class="lab-model-table"><caption class="sr-only">模型指标比较，{{ real ? '数值来自服务端已结束的批次对局' : '全部数值均来自手工示例' }}。当前按{{ metricNames[lab.metric] }}排序。</caption><thead><tr><th scope="col">模型 / 配置</th><th scope="col">胜率</th><th scope="col">发言质量</th><th scope="col">决策耗时</th><th scope="col">稳定性</th><th scope="col">局数</th><th scope="col">操作</th></tr></thead><tbody><tr v-for="row in lab.rows" :key="row.configId"><th scope="row"><PixelAvatar :variant="lab.models.find(item => item.id === row.modelId)?.avatar || 'fox'" :size="24" /><span>{{ row.name }}<small>{{ roleNames[row.role] }}{{ real ? ' · 服务端' : ' · 示例' }}</small></span></th><td><strong>{{ metricValue(row, 'winRate') }}</strong><progress v-if="row.winRate !== null" :value="row.winRate" max="100" aria-hidden="true" /></td><td><span class="lab-score quality">{{ metricValue(row, 'speechQuality') }}</span></td><td><span class="lab-score latency">{{ metricValue(row, 'latency') }}</span></td><td><span class="lab-score stability">{{ metricValue(row, 'stability') }}</span></td><td>{{ row.games }}</td><td><button class="lab-row-action" :aria-label="`查看 ${row.name} 模型详情`" @click="modelDetail = row.modelId; dialog = 'model'">···</button></td></tr></tbody></table></div><p v-else class="lab-preview-state">{{ lab.comparing ? '正在读取比较结果…' : lab.batch && !lab.completedGames ? (real ? '暂无已完成对局，刷新批次进度后查看比较。' : '暂无已完成样例，刷新批次进度后查看比较。') : '当前条件下没有比较数据。' }}</p></section>
            <section class="lab-panel lab-results"><div class="lab-panel-title"><h2 ref="resultHeading" tabindex="-1"><PixelIcon name="sun" :size="20" /> 实验结果概览</h2><button class="lab-link" @click="dialog = 'report'">查看详细报告 →</button></div><div class="lab-summary-grid"><div v-for="(label, key) in { winRate: '最高胜率', speechQuality: '最佳发言质量', latency: '最短决策耗时', stability: '最高稳定性' }" :key="key"><PixelIcon :name="key === 'winRate' ? 'check' : key === 'speechQuality' ? 'speech' : key === 'latency' ? 'clock' : 'shield'" :size="22" /><strong>{{ metricValue(lab.best[key], key) }}</strong><span>{{ label }}</span><small>{{ lab.best[key]?.name || '暂无数据' }}</small></div></div></section>
          </aside>
        </div>
        <footer class="px-panel lab-footer"><span class="lab-footer-state"><PixelIcon name="bottle" :size="19" />{{ batchState }}<small>{{ lab.batch ? `${lab.completedGames} / ${lab.totalGames} 局` : (real ? '经典九人局' : '经典九人样例') }}</small></span><div class="lab-footer-progress"><progress :value="lab.progress" max="100" :aria-label="`批次进度 ${lab.progress}%`" /><span>{{ lab.progress }}%</span></div><label v-if="!real && preview.match"><span class="sr-only">当前样例阶段</span><select :value="[...preview.chapters].reverse().find(event => event.at <= preview.position)?.at" @change="preview.seek(Number(($event.target as HTMLSelectElement).value))"><option v-for="chapter in preview.chapters" :key="chapter.id" :value="chapter.at">{{ chapter.title }}</option></select></label><label><span class="sr-only">日志级别</span><select v-model="logDetail"><option value="normal">日志级别：普通</option><option value="detail">日志级别：详细</option></select></label><label class="lab-auto-scroll"><input v-model="autoScroll" type="checkbox" />自动跟随日志</label><button :disabled="!lab.comparisons.length && !lab.batch?.results.length" @click="exportResults"><PixelIcon name="document" :size="16" />导出结果</button><button v-if="!real" :disabled="lab.running || lab.clearing || lab.submitting" class="lab-clear" @click="dialog = 'clear'"><PixelIcon name="close" :size="14" />清空记录</button></footer>
      </template>
    </main>
    <PixelDialog :open="!!dialog" :title="title" @update:open="value => { if (!value) dialog = null }">
      <template v-if="dialog === 'configs'"><p>选择已保存配置参与下一批次。批次使用提交时的配置快照，未保存的修改不会进入测试。</p><ul class="lab-saved-configs"><li v-for="config in lab.configs" :key="config.id"><label><input v-model="lab.selectedIds" type="checkbox" :value="config.id" />{{ config.name }} · {{ roleNames[config.role] }}</label><button class="lab-link" @click="lab.selectConfig(config.id); dialog = null">编辑</button></li></ul><p v-if="!lab.configs.length">还没有 Agent 配置。</p><button class="secondary-button px-button" @click="lab.newConfig(); dialog = null">新建配置</button></template>
      <template v-else-if="dialog === 'model' && model"><div class="player-public-detail"><PixelAvatar :variant="model.avatar" :size="48" /><strong>{{ model.name }}</strong></div><p>{{ model.description }}</p><p>{{ real ? '模型清单来自服务端：供应商默认模型，加上这个账号已保存配置里用过的模型。' : '这是界面演示用的模型档案。没有 API 密钥或真实模型调用，样例指标不代表真实模型能力。' }}</p></template>
      <template v-else-if="dialog === 'advanced'"><label class="field-label" for="lab-concurrency">并发上限（1–8）</label><input id="lab-concurrency" v-model.number="lab.options.concurrency" type="number" min="1" max="8" data-lab-field="concurrency" :aria-invalid="!!lab.fields.concurrency" /><p v-if="lab.fields.concurrency" class="lab-field-error">{{ lab.fields.concurrency }}</p><label v-if="lab.draft" class="field-label" for="lab-temperature">模型温度（0–1）</label><input v-if="lab.draft" id="lab-temperature" v-model.number="lab.draft.temperature" type="number" min="0" max="1" step="0.1" data-lab-field="temperature" :aria-invalid="!!lab.fields.temperature" /><p v-if="lab.fields.temperature" class="lab-field-error">{{ lab.fields.temperature }}</p><p>正式并发限制由服务端执行；本地演示不会调用模型。温度随 Agent 配置保存，演示速度只改变每次刷新推进的样例数量。</p></template>
      <template v-else-if="dialog === 'report'"><p>{{ lab.batch ? `${lab.batch.id} · ${lab.completedGames} / ${lab.totalGames} 局 · ${batchState}` : comparisonSource }}</p><p v-if="real">全部数值来自服务端已结束的批次对局：批次与真人对局走同一条规则与驱动，胜率按该配置所在阵营获胜的局数统计；规则基线座位不花模型成本。样本量小于 20 局时差异不具统计意义。</p><p v-else>所有结果和评分均为手工编写的界面样例，不作为模型性能或胜率的评测结论。每组对比各配置的独立样例，胜率按对应阵营胜出的样例数统计。</p><div class="lab-report-table"><table><thead><tr><th>配置</th><th>胜率</th><th>耗时</th><th>局数</th></tr></thead><tbody><tr v-for="row in lab.rows" :key="row.configId"><th>{{ row.name }}</th><td>{{ metricValue(row, 'winRate') }}</td><td>{{ metricValue(row, 'latency') }}</td><td>{{ row.games }}</td></tr></tbody></table></div><h3>{{ real ? '当前批次对局' : '当前批次样例记录' }}</h3><ol v-if="real && lab.batch?.games.length" class="lab-game-results"><li v-for="game in lab.batch.games" :key="game.index">第 {{ game.index }} 局 · {{ game.gameId || '尚未开局' }} · {{ gameLabel(game) }}<template v-if="game.gameId"><RouterLink :to="`/watch/${game.gameId}`">观战</RouterLink><RouterLink :to="`/games/${game.gameId}/replay`">回放</RouterLink><RouterLink :to="`/games/${game.gameId}/analysis`">单局分析</RouterLink></template></li></ol><ol v-else-if="lab.batch?.results.length" class="lab-game-results"><li v-for="result in lab.batch.results" :key="result.index">第 {{ result.index }} 组 · 种子 {{ result.seed }}<span v-for="outcome in result.outcomes" :key="outcome.configId">{{ lab.batch?.configs.find(config => config.id === outcome.configId)?.name }}：{{ outcome.winner }}</span><RouterLink v-if="result.gameId" :to="`/games/${result.gameId}/analysis`">单局分析</RouterLink></li></ol><p v-else>{{ real ? '暂无当前批次对局。' : '暂无当前批次结果。' }}</p><p v-if="!real">工作台是独立只读对局样例，可查看其 <RouterLink to="/games/demo/replay">回放</RouterLink> 与 <RouterLink to="/games/demo/analysis">AI 分析</RouterLink>。</p><button class="secondary-button px-button" :disabled="!lab.comparisons.length && !lab.batch?.results.length" @click="exportResults">导出 JSON</button><p v-if="exportFeedback" role="status">{{ exportFeedback }}</p></template>
      <template v-else-if="dialog === 'clear'"><p>清空当前标签页中的本地批次与比较记录，已保存的 Agent 配置保留。</p><button class="primary-button px-button px-button-primary" :disabled="lab.running || lab.clearing" @click="lab.clear().then(success => { if (success) dialog = null })">清空本地记录</button></template>
      <template v-else-if="dialog === 'seat' && inspected"><div class="player-public-detail"><PixelAvatar :variant="inspected.avatar" :size="46" /><strong>{{ inspected.seatNo }} 号 · {{ inspected.name }}</strong></div><p>{{ showRoles ? `赛后样例身份：${roleNames[inspected.disclosedRole!]}` : '当前视图隐藏身份标签。' }}</p><p>此玩家来自独立的已结束对局样例，不是当前批次产生的实时玩家。</p></template>
      <template v-else-if="dialog === 'rules'"><p>经典九人局：3 狼人、3 村民、1 预言家、1 女巫、1 猎人。本页不能修改游戏规则；正式批量对局须经过应用服务和 Game 聚合校验。</p></template>
      <template v-else-if="dialog === 'audio'"><p>浏览器暂时无法播放音效，可稍后重试。</p></template>
      <template v-else><p>{{ real ? 'WolfMind AI 实验室。配置、批次与比较结果都来自服务端：批次对局由与真人对局相同的规则与驱动推进，可以用回放与单局分析回到每一局。' : 'WolfMind AI 实验室。本页提供 Agent 配置、批次样例和模型比较的本地交互。真实模型执行、服务端队列和授权接口尚未接入。' }}</p><p v-if="real">页面上的中文策略预设映射到服务端的 <code>AGGRESSIVE / BALANCED / CONSERVATIVE</code> 三档打分权重；工具开关与自定义提示词没有服务端消费点，因此在这里不提供。</p></template>
    </PixelDialog>
  </div>
</template>
